        translation(itemDescKey(RecastingItems.CHAOS_FLAME), "色彩无定，在同一秒内可能呈现光谱上的任何颜色。", "Indeterminate colors, may display any color on the spectrum within the same second.");
        translation(itemDescKey(RecastingItems.OTHER_SHORE_FLAME), "冰冷的青白色，摇曳如烛，无温度。", "Cold bluish-white, flickering like a candle, without warmth.");
